insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-ek-226","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Acid-catalysed hydrolysis of methyl acetate in a large excess of water is treated as","options":["pseudo first order in the ester","second order in water","zero order in the ester","third order overall under all conditions"],"answer_index":0,"explanation":"[H$_2$O] is essentially constant, so the observed rate is first order in ester only.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-227","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a reaction that proceeds by several elementary steps, the overall order","options":["need not equal the molecularity of any one step, and is found only by experiment","is always equal to the number of steps","must equal the molecularity of the last step","is undefined if a catalyst is present"],"answer_index":0,"explanation":"Order is a property of the observed rate law. Molecularity belongs to individual steps.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-228","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Termolecular elementary steps are rare because","options":["a simultaneous collision of three molecules is statistically improbable","three molecules can never share electrons","the collision theory forbids $n = 3$ exactly","Faraday's laws prohibit them"],"answer_index":0,"explanation":"Two-body collisions are common; a third body arriving in the same instant is unlikely, so $n = 3$ steps are scarce.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-229","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A rate constant reported as L$^2$ mol$^{-2}$ s$^{-1}$ indicates that the reaction is","options":["third order overall","first order overall","zero order overall","fractional order of ½"],"answer_index":0,"explanation":"Units of $k$ are (conc.)$^{1-n}$ (time)$^{-1}$. L$^2$ mol$^{-2}$ s$^{-1}$ corresponds to $n = 3$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-230","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Mechanism: fast equilibrium A + B ⇌ I, followed by slow I → P. The observed order in A and the molecularity of the slow step are","options":["first order in A, and unimolecular","second order in A, and bimolecular","zero order in A, and termolecular","first order in A, and bimolecular"],"answer_index":0,"explanation":"The RDS is unimolecular in I. Substituting [I] = $K[\\mathrm{A}][\\mathrm{B}]$ makes the rate first order in A (and in B).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"order-molecularity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-231","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integrated first-order rate law is commonly written","options":["$\\ln([\\mathrm{A}]_0/[\\mathrm{A}]) = kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$","$[\\mathrm{A}]^2 = kt$"],"answer_index":0,"explanation":"Integration of $-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = k[\\mathrm{A}]$ yields a linear plot of $\\ln[\\mathrm{A}]$ versus $t$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-232","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a zero-order decay the concentration falls linearly according to","options":["$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$\\ln[\\mathrm{A}] = \\ln[\\mathrm{A}]_0 - kt$","$1/[\\mathrm{A}] = 1/[\\mathrm{A}]_0 + kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 e^{+kt}$"],"answer_index":0,"explanation":"Rate $= k$ (constant), so [A] drops at a constant slope $-k$ until the reactant is exhausted.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-233","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The integrated law for a simple second-order reaction 2A → products is","options":["$1/[\\mathrm{A}] - 1/[\\mathrm{A}]_0 = kt$","$\\ln([\\mathrm{A}]_0/[\\mathrm{A}]) = kt$","$[\\mathrm{A}] = [\\mathrm{A}]_0 - kt$","$[\\mathrm{A}]_0 - [\\mathrm{A}] = k\\ln t$"],"answer_index":0,"explanation":"Integration of $-\\mathrm{d}[\\mathrm{A}]/\\mathrm{d}t = k[\\mathrm{A}]^2$ produces the reciprocal-concentration relation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-234","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A hallmark of first-order kinetics is that the half-life","options":["does not depend on the starting concentration","is proportional to $[\\mathrm{A}]_0$","is inversely proportional to $[\\mathrm{A}]_0$","grows as $[\\mathrm{A}]_0^2$"],"answer_index":0,"explanation":"$t_{1/2} = \\ln 2 / k$ contains no $[\\mathrm{A}]_0$. Each successive half-life has the same duration.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-235","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Zero-order half-life grows when the initial concentration is raised because","options":["$t_{1/2} = [\\mathrm{A}]_0 / (2k)$","$t_{1/2} = \\ln 2 / k$","$t_{1/2} = 1 / (k[\\mathrm{A}]_0)$","$t_{1/2}$ is independent of $[\\mathrm{A}]_0$"],"answer_index":0,"explanation":"A constant rate needs longer to consume half of a larger starting amount.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"integrated-half-life","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
    answer_index int,
    explanation text,
    images jsonb,
    source jsonb,
    difficulty text,
    concept_id text,
    appear_count int,
    years jsonb,
